window.AUTH=window.AUTH||{};window.AUTH["20-315"]={"d":"20-315","id":"2020/20-315","n":"Sanchez v. Mayorkas","briefs":[{"k":"petitioner","label":"Brief of petitioners Jose Santos Sanchez, et al.","date":"2021-02-22","url":"https://www.supremecourt.gov/DocketPDF/20/20-315/169515/20210222121912629_Sanchez%20Merits%20Brief%20and%20Appendix.pdf","side":"pet","n":64},{"k":"respondent","label":"Brief of respondents Alejandro N. Mayorkas, Secretary of Homeland Security, et al.","date":"2021-03-24","url":"https://www.supremecourt.gov/DocketPDF/20/20-315/172925/20210324211307240_20-315bsUnitedStates.pdf","side":"res","n":117},{"k":"reply","label":"Reply of petitioner Jose Santos Sanchez, et ux.","date":"2021-04-09","url":"https://www.supremecourt.gov/DocketPDF/20/20-315/175319/20210409122214447_Sanchez%20Reply%20Brief.pdf","side":"pet","n":35}],"opinion":"https://www.supremecourt.gov/opinions/20pdf/593us2r43_22p3.pdf","tr":true,"items":[{"t":"case","label":"Advocate Health Care Network v. Stapleton","cite":"137 S. Ct. 1652","y":2017,"id":"2016/16-74","sc":1,"by":{"0":"22, 23, 24, 32","1":"37, 38","2":"3, 4, 6"}},{"t":"case","label":"Alaska Dep’t of Envt’l Conservation v. EPA","cite":"540 U.S. 461","y":2004,"id":"2003/02-658","sc":1,"by":{"0":"45"}},{"t":"case","label":"Ali v. Fed. Bureau of Prisons","cite":"552 U.S. 214","y":2008,"id":"2007/06-9130","sc":1,"by":{"0":"21","1":"37"},"q":[{"src":"brief","b":0,"text":"are customs officers when they enforce customs laws.","cite":"552 U.S. 214, 227 n.6"}]},{"t":"case","label":"Ardestani v. INS","cite":"502 U.S. 129","y":1991,"id":"1991/90-1141","sc":1,"by":{"0":"46"}},{"t":"case","label":"Azar v. Allina Health Servs.","cite":"139 S. Ct. 1804","y":2019,"id":"2018/17-1484","sc":1,"by":{"0":"33","2":"14"},"q":[{"src":"brief","b":0,"text":"doubtful . . . that Congress sought to accomplish in a ‘surpassingly strange manner’ what it could have accomplished in a much more straightforward way.","cite":"139 S. Ct. 1804, 1813"}]},{"t":"case","label":"Barnhart v. Walton","cite":"535 U.S. 212","y":2002,"id":"2001/00-1937","sc":1,"by":{"0":"43, 47","1":"45","2":"22, 23, 24"},"q":[{"src":"brief","b":0,"text":"the interstitial nature of the legal question, the related expertise of the Agency, the importance of the question to administration of the statute, the complexity of that administration, and the careful consideration the Agency has given the question over a long period of time,","cite":"535 U.S. 212, 222"}]},{"t":"case","label":"Bruesewitz v. Wyeth LLC","cite":"562 U.S. 223","y":2011,"id":"2010/09-152","sc":1,"by":{"0":"32"}},{"t":"case","label":"Carcieri v. Salazar","cite":"555 U.S. 379","y":2009,"id":"2008/07-526","sc":1,"by":{"0":"33"}},{"t":"case","label":"Chevron, U.S.A., Inc. v. Nat. Res. Def. Council, Inc.","cite":"467 U.S. 837","y":1984,"id":"1983/82-1005","sc":1,"by":{"0":"passim","1":"42","2":"passim"},"q":[{"src":"argument","who":"Mr. Huston","text":"And even if the Court was not inclined to apply Chevron deference, the result would be the same. We think our interpretation is the better one."},{"src":"argument","who":"Justice Breyer","text":"And if there are no others, then aren't we in the world where there is ambiguity in the statute and we have to get into the Chevron issue, which, as you well know, is a big issue where there are two sides."},{"src":"argument","who":"Mr. Huston","text":"So we think that it is not necessary for the Court to reach -- to get into Chevron deference here because we simply think we have the better interpretation of the statutory text."}]},{"t":"case","label":"Christensen v. Harris Cnty.","cite":"529 U.S. 576","y":2000,"id":"1999/98-1167","sc":1,"by":{"0":"44, 45, 48","2":"20"},"q":[{"src":"brief","b":0,"text":"only to the extent that those interpretations have the ‘power to persuade.’","cite":"529 U.S. 576, 587"}]},{"t":"case","label":"Cmty. for Creative Non-Violence v. Reid","cite":"490 U.S. 730","y":1989,"id":"1988/88-293","sc":1,"by":{"0":"41"},"q":[{"src":"brief","b":0,"text":"is the result of a series of carefully crafted compromises.","cite":"490 U.S. 730, 748 n.14"}]},{"t":"case","label":"Cnty. of Maui v. Haw. Wildlife Fund","cite":"140 S. Ct. 1462","y":2020,"id":"2019/18-260","sc":1,"by":{"0":"36"},"q":[{"src":"brief","b":0,"text":"advance[s], in a manner consistent with the statute’s language, the statutory purposes that Congress sought to achieve.","cite":"140 S. Ct. 1462, 1476"}]},{"t":"case","label":"Culbertson v. Berryhill","cite":"139 S. Ct. 517","y":2019,"id":"2018/17-773","sc":1,"by":{"0":"17"}},{"t":"case","label":"Cyan, Inc. v. Beaver Cnty. Emps. Ret. Fund","cite":"138 S. Ct. 1061","y":2018,"id":"2017/15-1439","sc":1,"by":{"0":"31","1":"28","2":"12"},"q":[{"src":"brief","b":0,"text":"it presumably would have done so— just by adding a letter, a number, and a few parentheticals.","cite":"138 S. Ct. 1061, 1070"},{"src":"brief","b":2,"text":"it presumably would have done so—just by adding a letter, a number, and a few parentheticals.","cite":"138 S. Ct. 1061, 1070"}]},{"t":"case","label":"Flores v. USCIS","cite":"718 F.3d 548","y":2013,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/718/548/","by":{"0":"49"},"q":[{"src":"brief","b":0,"text":"[b]eing consistently wrong does not afford the agency more deference than having valid reasoning.","cite":"718 F.3d 548, 555"}]},{"t":"case","label":"Gonzales v. Oregon","cite":"546 U.S. 243","y":2006,"id":"2005/04-623","sc":1,"by":{"0":"43","2":"20"},"q":[{"src":"brief","b":2,"text":"restate[s] the terms of the statute itself,","cite":"546 U.S. 243, 256-57"}]},{"t":"case","label":"Gutierrez-Brizuela v. Lynch","cite":"834 F.3d 1142","y":2016,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/834/1142/","by":{"0":"42"}},{"t":"case","label":"Hernandez de Gutierrez v. Barr","cite":"2020 WL 5764281","y":2020,"court":"D. Minn. Sept. 28","by":{"0":"44, 45","1":"44"}},{"t":"case","label":"INS v. Aguirre-Aguirre","cite":"526 U.S. 415","y":1999,"id":"1998/97-1754","sc":1,"by":{"0":"48","1":"42, 45","2":"22"},"q":[{"src":"brief","b":0,"text":"in the course of considering and determining cases before it.","cite":"526 U.S. 415, 425"}]},{"t":"case","label":"INS v. Cardoza-Fonseca","cite":"480 U.S. 421","y":1987,"id":"1986/85-782","sc":1,"by":{"0":"41, 47","1":"9, 41","2":"16"},"q":[{"src":"brief","b":0,"text":"Few principles of statutory construction are more compelling than the proposition that Congress does not intend sub silentio to enact statutory language that it has earlier discarded in favor of other language.","cite":"480 U.S. 421, 442-43"},{"src":"brief","b":2,"text":"Few principles of statutory construction are more compelling than the proposition that Congress does not intend sub silentio to enact statutory language that it has earlier discarded in favor of other language.","cite":"480 U.S. 421, 442-43"}]},{"t":"case","label":"Long Island Care at Home, Ltd. v. Coke","cite":"551 U.S. 158","y":2007,"id":"2006/06-593","sc":1,"by":{"0":"43, 44, 46","1":"46","2":"21"},"q":[{"src":"brief","b":0,"text":"focused fully upon the matter in question,","cite":"551 U.S. at 165"}]},{"t":"case","label":"Merit Mgmt. Grp., LP v. FTI Consulting, Inc.","cite":"138 S. Ct. 883","y":2018,"id":"2017/16-784","sc":1,"by":{"0":"26, 30"},"q":[{"src":"brief","b":0,"text":"Adjustment of status of nonimmigrant to that of person admitted for permanent residence","cite":"138 S. Ct. 883, 893"}]},{"t":"case","label":"Negusie v. Holder","cite":"555 U.S. 511","y":2009,"id":"2008/07-499","sc":1,"by":{"0":"44, 48, 49","1":"41"},"q":[{"src":"brief","b":0,"text":"give[] ambiguous statutory terms ‘concrete meaning through a process of case-by-case adjudication.’","cite":"555 U.S. at 517"}]},{"t":"case","label":"NLRB v. SW Gen., Inc.","cite":"137 S. Ct. 929","y":2017,"id":"2016/15-1251","sc":1,"by":{"0":"30","1":"28"},"q":[{"src":"brief","b":0,"text":"When Congress want[s] to refer only to a particular subsection or paragraph, it sa[ys] so.","cite":"137 S. Ct. 929, 938-39"}]},{"t":"case","label":"Obduskey v. McCarthy & Holthus LLP","cite":"139 S. Ct. 1029","y":2019,"id":"2018/17-1307","sc":1,"by":{"0":"41"},"q":[{"src":"brief","b":0,"text":"Given these conflicting proposals, the Act’s present language has all the earmarks of a compromise.","cite":"139 S. Ct. 1029, 1038"}]},{"t":"case","label":"Pereira v. Sessions","cite":"138 S. Ct. 2105","y":2018,"id":"2017/17-459","sc":1,"by":{"0":"42"}},{"t":"case","label":"RadLAX Gateway Hotel, LLC v. Amalgamated Bank","cite":"566 U.S. 639","y":2012,"id":"2011/11-166","sc":1,"by":{"0":"33"}},{"t":"case","label":"Ramirez v. Brown","cite":"852 F.3d 954","y":2017,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/852/954/","by":{"0":"38","1":"44"}},{"t":"case","label":"Ramos v. Nielsen","cite":"336 F. Supp. 3d 1075","y":2018,"court":"N.D. Cal.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/336/1075/","by":{"0":"10","1":"7"}},{"t":"case","label":"Ramos v. Wolf","cite":"975 F.3d 872","y":2020,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/975/872/","by":{"0":"10"}},{"t":"case","label":"S. Pac. Co. v. Gileo","cite":"351 U.S. 493","y":1956,"id":"1955/257","sc":1,"by":{"0":"21, 23, 25","2":"16"}},{"t":"case","label":"Sanchez v. Sec’y, DHS","cite":"967 F.3d 242","y":2020,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/967/242/","by":{"0":"1"},"q":[{"src":"opinion","who":"Opinion of the Court (Justice Kagan)","text":"a grant of TPS does not constitute an `admission' into the United States.","cite":"967 F. 3d 242, 252"}]},{"t":"case","label":"Santos Sanchez v. Johnson","cite":"2018 WL 6427894","y":2018,"court":"D.N.J. Dec. 7","by":{"0":"1"}},{"t":"case","label":"SAS Inst. v. Iancu","cite":"138 S. Ct. 1348","y":2018,"id":"2017/16-969","sc":1,"by":{"0":"42"}},{"t":"case","label":"Skidmore v. Swift & Co.","cite":"323 U.S. 134","y":1944,"id":"1940-1955/12","sc":1,"by":{"0":"17, 44, 48","2":"20, 24"}},{"t":"case","label":"Solorzano v. Mayorkas, --- F.3d ---","cite":"2021 WL 365830","y":2021,"court":"5th Cir. Feb. 3","by":{"0":"14"}},{"t":"case","label":"Sturgeon v. Frost","cite":"139 S. Ct. 1066","y":2019,"id":"2018/17-949","sc":1,"by":{"0":"21","1":"36","2":"7"},"q":[{"src":"brief","b":0,"text":"as if it were really something else.","cite":"139 S. Ct. 1066, 1081"},{"src":"brief","b":1,"text":"[w]hen one thing is ‘considered as’ or ‘deemed to be’ another, it is treated ‘as if it were really something else.’","cite":"139 S. Ct. 1066, 1081"}]},{"t":"case","label":"United States v. Atl. Rsch. Corp.","cite":"551 U.S. 128","y":2007,"id":"2006/06-562","sc":1,"by":{"0":"31"}},{"t":"case","label":"United States v. Mead Corp.","cite":"533 U.S. 218","y":2001,"id":"2000/99-1434","sc":1,"by":{"0":"passim","1":"46","2":"19, 20, 21, 22"},"q":[{"src":"brief","b":0,"text":"when it appears that Congress delegated authority to the agency generally to make rules carrying the force of law, and that the agency interpretation claiming deference was promulgated in the exercise of that authority.","cite":"533 U.S. at 227"},{"src":"brief","b":0,"text":"when it provides for a relatively formal administrative procedure tending to foster the fairness and deliberation that should underlie a pronouncement of such force.","cite":"533 U.S. at 230"},{"src":"brief","b":1,"text":"the fruit[ ] of notice-andcomment rulemaking.","cite":"533 U.S. 218, 230"},{"src":"brief","b":2,"text":"make rules carrying the force of law","cite":"533 U.S. 218, 226-27"}]},{"t":"case","label":"Util. Air Regul. Grp. v. EPA","cite":"573 U.S. 302","y":2014,"id":"2013/12-1146","sc":1,"by":{"0":"42, 49"}},{"t":"case","label":"Velasquez v. Barr","cite":"979 F.3d 572","y":2020,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/979/572/","by":{"0":"14"}},{"t":"case","label":"Yates v. United States","cite":"574 U.S. 528","y":2015,"id":"2014/13-7451","sc":1,"by":{"0":"27"}},{"t":"usc","label":"5 U.S.C. § 701","url":"https://www.law.cornell.edu/uscode/text/5/701","stext":{"head":"§701. Application; definitions","paras":[[0,"(a) This chapter applies, according to the provisions thereof, except to the extent that—"],[1,"(1) statutes preclude judicial review; or"],[1,"(2) agency action is committed to agency discretion by law."],[0,"(b) For the purpose of this chapter—"],[1,"(1) \"agency\" means each authority of the Government of the United States, whether or not it is within or subject to review by another agency, but does not include—"],[2,"(A) the Congress;"],[2,"(B) the courts of the United States;"],[2,"(C) the governments of the territories or possessions of the United States;"],[2,"(D) the government of the District of Columbia;"],[2,"(E) agencies composed of representatives of the parties or of representatives of organizations of the parties to the disputes determined by them;"],[2,"(F) courts martial and military commissions;"],[2,"(G) military authority exercised in the field in time of war or in occupied territory; or"],[2,"(H) functions conferred by sections 1738, 1739, 1743, and 1744 of title 12; subchapter II of chapter 471 of title 49; or sections 1884, 1891–1902, and former section 1641(b)(2), of title 50, appendix; 1 and"],[1,"(2) \"person\", \"rule\", \"order\", \"license\", \"sanction\", \"relief\", and \"agency action\" have the meanings given them by section 551 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/701?type=usc&year=mostrecent&link-type=html"},"by":{"0":"13, 46","1":"8"}},{"t":"law","label":"Pub. L. No. 85-700","url":"https://www.govinfo.gov/link/statute/72/699","by":{"0":"26"}},{"t":"law","label":"Chinese Student Protection Act, Pub. L. No. 102-404","by":{"0":"35","1":"23"}},{"t":"usc","label":"29 U.S.C. § 1001","url":"https://www.law.cornell.edu/uscode/text/29/1001","by":{"0":"22"}},{"t":"law","label":"Pub. L. No. 101-649","url":"https://www.govinfo.gov/link/statute/104/4978","by":{"0":"passim","1":"4","2":"2, 8, 9, 12"}},{"t":"law","label":"and regulations—continued: Immigration and Nationality Act, Pub. L. No. 82-414","url":"https://www.govinfo.gov/link/statute/66/163","by":{"0":"passim","2":"passim"}},{"t":"usc","label":"8 U.S.C. § 1101","url":"https://www.law.cornell.edu/uscode/text/8/1101","subs":["(a)(13)(A)","(a)(3)","(a)(4)(1988)","(a)(13)(1988)","(a)(13)(B)","(a)(15)","(a)(15)(D)(i)","(a)(15)(H)(i)(B)","(a)(15)(U)","(a)(27)(J)","(a)(27)(K)","(a)(51)"],"stext":{"head":"§1101. Definitions","paras":[[0,"(a) As used in this chapter—"],[0,"(1) The term \"administrator\" means the official designated by the Secretary of State pursuant to section 1104(b) of this title."],[0,"(2) The term \"advocates\" includes, but is not limited to, advises, recommends, furthers by overt act, and admits belief in."],[0,"(3) The term \"alien\" means any person not a citizen or national of the United States."],[0,"(4) The term \"application for admission\" has reference to the application for admission into the United States and not to the application for the issuance of an immigrant or nonimmigrant visa."],[0,"(5) The term \"Attorney General\" means the Attorney General of the United States."],[0,"(6) The term \"border crossing identification card\" means a document of identity bearing that designation issued to an alien who is lawfully admitted for permanent residence, or to an alien who is a resident in foreign contiguous territory, by a consular officer or an immigration officer for the purpose of crossing over the borders between the United States and foreign contiguous territory in accordance with such conditions for its issuance and use as may be prescribed by regulations. Such regulations shall provide that (A) each such document include a biometric identifier (such as the fingerprint or handprint of the alien) that is machine readable and (B) an alien presenting a border crossing identification card is not permitted to cross over the border into the United States unless the biometric identifier contained on the card matches the appropriate biometric characteristic of the alien."],[0,"(7) The term \"clerk of court\" means a clerk of a naturalization court."],[0,"(8) The terms \"Commissioner\" and \"Deputy Commissioner\" mean the Commissioner of Immigration and Naturalization and a Deputy Commissioner of Immigration and Naturalization, respectively."],[0,"(9) The term \"consular officer\" means any consular, diplomatic, or other officer or employee of the United States designated under regulations prescribed under authority contained in this chapter, for the purpose of issuing immigrant or nonimmigrant visas or, when used in subchapter III, for the purpose of adjudicating nationality."],[0,"(10) The term \"crewman\" means a person serving in any capacity on board a vessel or aircraft."],[0,"(11) The term \"diplomatic visa\" means a nonimmigrant visa bearing that title and issued to a nonimmigrant in accordance with such regulations as the Secretary of State may prescribe."],[0,"(12) The term \"doctrine\" includes, but is not limited to, policies, practices, purposes, aims, or procedures."],[0,"(13)(A) The terms \"admission\" and \"admitted\" mean, with respect to an alien, the lawful entry of the alien into the United States after inspection and authorization by an immigration officer."],[0,"(B) An alien who is paroled under section 1182(d)(5) of this title or permitted to land temporarily as an alien crewman shall not be considered to have been admitted."],[0,"(C) An alien lawfully admitted for permanent residence in the United States shall not be regarded as seeking an admission into the United States for purposes of the immigration laws unless the alien—"],[1,"(i) has abandoned or relinquished that status,"],[1,"(ii) has been absent from the United States for a continuous period in excess of 180 days,"],[1,"(iii) has engaged in illegal activity after having departed the United States,"],[1,"(iv) has departed from the United States while under legal process seeking removal of the alien from the United States, including removal proceedings under this chapter and extradition proceedings,"],[1,"(v) has committed an offense identified in section 1182(a)(2) of this title, unless since such offense the alien has been granted relief under section 1182(h) or 1229b(a) of this title, or"],[1,"(vi) is attempting to enter at a time or place other than as designated by immigration officers or has not been admitted to the United States after inspection and authorization by an immigration officer."],[0,"(14) The term \"foreign state\" includes outlying possessions of a foreign state, but self-governing dominions or territories under mandate or trusteeship shall be regarded as separate foreign states."],[0,"(15) The term \"immigrant\" means every alien except an alien who is within one of the following classes of nonimmigrant aliens—"],[1,"(A)(i) an ambassador, public minister, or career diplomatic or consular officer who has been accredited by a foreign government, recognized de jure by the United States and who is accepted by the President or by the Secretary of State, and the members of the alien's immediate family;"],[1,"(ii) upon a basis of reciprocity, other officials and employees who have been accredited by a foreign government recognized de jure by the United States, who are accepted by the Secretary of State, and the members of their immediate families; and"],[1,"(iii) upon a basis of reciprocity, attendants, servants, personal employees, and members of their immediate families, of the officials and employees who have a nonimmigrant status under (i) and (ii) above;"],[1,"(B) an alien (other than one coming for the purpose of study or of performing skilled or unskilled labor or as a representative of foreign press, radio, film, or other foreign information media coming to engage in such vocation) having a residence in a foreign country which he has no intention of abandoning and who is visiting the United States temporarily for business or temporarily for pleasure;"],[1,"(C)(i) an alien in immediate and continuous transit through the United States, for a period not to exceed 29 days;"],[1,"(ii) an alien who qualifies as a person entitled to pass in transit to and from the United Nations Headquarters District (as defined in section 4309a(e) of title 22) and foreign countries, under the provisions of paragraphs (3), (4), and (5) of section 11 of the Agreement regarding the Headquarters of the United Nations, done at Lake Success June 26, 1947 (61 Stat. 758); or"],[1,"(iii) an alien passing in transit through the United States to board a vessel on which the alien will perform, or to disembark from a vessel on which the alien performed, ship-to-ship liquid cargo transfer operations to or from another vessel engaged in foreign trade, for a period not to exceed 180 days;"],[1,"(D)(i) an alien crewman serving in good faith as such in a capacity required for normal operation and service on board a vessel, as defined in section 1288(a) of this title (other than a fishing vessel having its home port or an operating base in the United States), or aircraft, who intends to land temporarily and solely in pursuit of his calling as a crewman and to depart from the United States with the vessel or aircraft on which he arrived or some other vessel or aircraft;"],[1,"(ii) an alien crewman serving in good faith as such in any capacity required for normal operations and service aboard a fishing vessel having its home port or an operating base in the United States who intends to land temporarily in Guam or the Commonwealth of the Northern Mariana Islands and solely in pursuit of his calling as a crewman and to depart from Guam or the Commonwealth of the Northern Mariana Islands with the vessel on which he arrived; or"],[1,"(iii) an alien crewman performing ship-to-ship liquid cargo transfer operations to or from another vessel engaged in foreign trade, who intends to land temporarily solely in pursuit of the alien's responsibilities as a crewman and to depart from the United States on the vessel on which the alien arrived or on another vessel or aircraft, for a period not to exceed 180 days;"],[1,"(E) an alien entitled to enter the United States under and in pursuance of the provisions of a treaty of commerce and navigation between the United States and the foreign state of which the alien is a national (or, in the case of an alien who acquired the relevant nationality through a financial investment and who has not previously been granted status under this subparagraph, the foreign state of which the alien is a national and in which the alien has been domiciled for a continuous period of not less than 3 years at any point before applying for a nonimmigrant visa under this subparagraph), and the spouse and children of any such alien if accompanying or following to join such alien; (i) solely to carry on substantial trade, including trade in services or trade in technology, principally between the United States and the foreign state of which the alien is a national; (ii) solely to develop and direct the operations of an enterprise in which the alien has invested, or of an enterprise in which the alien is actively in the process of investing, a substantial amount of capital; or (iii) solely to perform services in a specialty occupation in the United States if the alien is a national of the Commonwealth of Australia and with respect to whom the Secretary of Labor determines and certifies to the Secretary of Homeland Security and the Secretary of State that the intending employer has filed with the Secretary of Labor an attestation under section 1182(t)(1) of this title;"],[1,"(F)(i) an alien having a residence in a foreign country which he has no intention of abandoning, who is a bona fide student qualified to pursue a full course of study and who seeks to enter the United States temporarily and solely for the purpose of pursuing such a course of study consistent with section 1184(l) 1 of this title at an established college, university, seminary, conservatory, academic high school, elementary school, or other academic institution or in an accredited language training program in the United States, particularly designated by him and approved by the Attorney General after consultation with the Secretary of Education, which institution or place of study shall have agreed to report to the Attorney General the termination of attendance of each nonimmigrant student, and if any such institution of learning or place of study fails to make reports promptly the approval shall be withdrawn, (ii) the alien spouse and minor children of any alien described in clause (i) if accompanying or following to join such an alien, and (iii) an alien who is a national of Canada or Mexico, who maintains actual residence and place of abode in the country of nationality, who is described in clause (i) except that the alien's qualifications for and actual course of study may be full or part-time, and who commutes to the United States institution or place of study from Canada or Mexico;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1101?type=usc&year=mostrecent&link-type=html"},"by":{"0":"20, 26","1":"2, 35, 35, 31, 19, 19, 19, 19, 19, 20, 20, 20, 20","2":"5, 7, 8"},"q":[{"src":"brief","b":0,"text":"the lawful entry of the alien into the United States after inspection and authorization by an immigration officer.","cite":"8 U.S.C. § 1101(a)(13)(A)"},{"src":"brief","b":1,"text":"the lawful entry of the alien into the United States after inspection and authorization by an immigration officer.","cite":"8 U.S.C. 1101(a)(13)(A)"},{"src":"brief","b":1,"text":"‘lawful entry * * * into the United States after inspection and authorization by an immigration officer,’","cite":"8 U.S.C. 1101(a)(13)(A)"}]},{"t":"usc","label":"8 U.S.C. § 1187","url":"https://www.law.cornell.edu/uscode/text/8/1187","by":{"0":"19"},"q":[{"src":"brief","b":0,"text":"previously . . . admitted without a visa under this section . . . must not have failed to comply with the conditions of any previous admission as such a nonimmigrant.","cite":"8 U.S.C. § 1187(a)(7)"}]},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"2"}},{"t":"reg","label":"8 C.F.R. § 1.4","url":"https://www.ecfr.gov/current/title-8/section-1.4","subs":["(d)"],"by":{"0":"27"}},{"t":"reg","label":"20 C.F.R. § 655.700","url":"https://www.ecfr.gov/current/title-20/section-655.700","by":{"0":"20"}},{"t":"reg","label":"Continuation of Documentation for Beneficiaries of Temporary Protected Status Designations for El Salvador, Haiti, Nicaragua, Sudan, Hondura, 85 Fed. Reg. 79,208","url":"https://www.govinfo.gov/link/fr/85/79208","by":{"0":"10","1":"7"}},{"t":"reg","label":"Designation of El Salvador Under Temporary Protected Status Program, 66 Fed. Reg. 14,214","url":"https://www.govinfo.gov/link/fr/66/14214","by":{"0":"10, 11","1":"7"}},{"t":"reg","label":"Designation of Haiti for Temporary Protected Status, 75 Fed. Reg. 3476","url":"https://www.govinfo.gov/link/fr/75/3476","by":{"0":"9"}},{"t":"reg","label":"Exec. Order 12,711, 55 Fed. Reg. 13,897","url":"https://www.govinfo.gov/link/fr/55/13897","by":{"0":"34, 35","1":"22, 30","2":"14, 15"}},{"t":"reg","label":"Extension of the Designation of El Salvador for Temporary Protected Status and Automatic Extension of Employment Authorization Documentation, 75 Fed. Reg. 39,556","url":"https://www.govinfo.gov/link/fr/75/39556","by":{"0":"10"}},{"t":"reg","label":"Extension of the Designation of Syria for Temporary Protected Status, 84 Fed. Reg. 49,751","url":"https://www.govinfo.gov/link/fr/84/49751","by":{"0":"9"}},{"t":"reg","label":"Extension of El Salvador for Temporary Protected Status, 81 Fed. Reg. 44,645","url":"https://www.govinfo.gov/link/fr/81/44645","by":{"0":"10"}},{"t":"reg","label":"Six-Month Extension of Temporary Protected Status Benefits for Orderly Transition Before Termination of Guinea’s Designation for Temporary P, 81 Fed. Reg. 66,064","url":"https://www.govinfo.gov/link/fr/81/66064","by":{"0":"9"}},{"t":"reg","label":"Six-Month Extension of Temporary Protected Status Benefits for Orderly Transition Before Termination of Liberia’s Designation for Temporary , 81 Fed. Reg. 66,059","url":"https://www.govinfo.gov/link/fr/81/66059","by":{"0":"9"}},{"t":"reg","label":"Six-Month Extension of Temporary Protected Status Benefits for Orderly Transition Before Termination of Sierra Leone’s Designation for Tempo, 81 Fed. Reg. 66,054","url":"https://www.govinfo.gov/link/fr/81/66054","by":{"0":"9"}},{"t":"reg","label":"Termination of the Designation of El Salvador for Temporary Protected Status, 83 Fed. Reg. 2654","url":"https://www.govinfo.gov/link/fr/83/2654","by":{"0":"10","1":"7"}},{"t":"case","label":"Barton v. Barr","cite":"140 S. Ct. 1442","y":2020,"id":"2019/18-725","sc":1,"by":{"1":"3"}},{"t":"case","label":"Buck v. Davis","cite":"137 S. Ct. 759","y":2017,"id":"2016/15-8049","sc":1,"by":{"1":"39"}},{"t":"case","label":"Burgess v. United States","cite":"553 U.S. 124","y":2008,"id":"2007/06-11429","sc":1,"by":{"1":"15"}},{"t":"case","label":"Gomez v. Lynch","cite":"831 F.3d 652","y":2016,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/831/652/","by":{"1":"16, 34"},"q":[{"src":"brief","b":1,"text":"permission to be present in the United States.","cite":"831 F.3d 652, 658"},{"src":"brief","b":1,"text":"as unadmitted (which would render him subject to removal and a variety of other sanctions plainly incompatible with his status).","cite":"831 F.3d at 661"}]},{"t":"case","label":"Guerrero v. Nielsen","cite":"742 Fed. Appx. 793","y":2018,"court":"5th Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./742/793/","by":{"1":"37"}},{"t":"case","label":"Holder v. Martinez Gutierrez","cite":"566 U.S. 583","y":2012,"id":"2011/10-1542","sc":1,"by":{"1":"12, 35, 46, 48"},"q":[{"src":"brief","b":1,"text":"need not decide if the statute permits any other construction.","cite":"566 U.S. 583, 591"},{"src":"brief","b":1,"text":"if it is a reasonable construction of the statute, whether or not it is the only possible interpretation or even the one a court might think best.","cite":"566 U.S. at 591"}]},{"t":"case","label":"Kimble v. Marvel Entm’t, LLC","cite":"576 U.S. 446","y":2015,"id":"2014/13-720","sc":1,"by":{"1":"49"}},{"t":"case","label":"Kisor v. Wilkie","cite":"139 S. Ct. 2400","y":2019,"id":"2018/18-15","sc":1,"by":{"1":"47","2":"19, 20"}},{"t":"case","label":"Melendez v. McAleenan","cite":"928 F.3d 425","y":2019,"url":"https://www.courtlistener.com/c/F.3d/928/425/","by":{"1":"19"}},{"t":"case","label":"Murphy v. Smith","cite":"138 S. Ct. 784","y":2018,"id":"2017/16-1067","sc":1,"by":{"1":"36"}},{"t":"case","label":"Nijhawan v. Holder","cite":"557 U.S. 29","y":2009,"id":"2008/08-495","sc":1,"by":{"1":"37"}},{"t":"case","label":"Qi-Zhuo v. Meissner","cite":"70 F.3d 136","y":1995,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/70/136/","by":{"1":"24"}},{"t":"case","label":"Scialabba v. de Osorio","cite":"573 U.S. 41","y":2014,"id":"2013/12-930","sc":1,"by":{"1":"41"}},{"t":"case","label":"Serrano v. U.S. Attorney Gen.","cite":"655 F.3d 1260","y":2011,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/655/1260/","by":{"1":"49"}},{"t":"law","label":"Pub. L. No. 105-119","url":"https://www.govinfo.gov/link/plaw/105/public/119","by":{"1":"24"}},{"t":"usc","label":"5 U.S.C. § 706","url":"https://www.law.cornell.edu/uscode/text/5/706","subs":["(2)(A)"],"by":{"1":"13, 15"}},{"t":"law","label":"Pub. L. No. 100-204","url":"https://www.govinfo.gov/link/statute/101/1400","by":{"1":"23","2":"16"}},{"t":"law","label":"Pub. L. No. 104-208","url":"https://www.govinfo.gov/link/plaw/104/public/208","by":{"1":"35"}},{"t":"usc","label":"8 U.S.C. § 1103","url":"https://www.law.cornell.edu/uscode/text/8/1103","subs":["(a)(1988)","(a)(1)","(g)"],"by":{"1":"43, 2, 2"}},{"t":"usc","label":"8 U.S.C. § 1182","url":"https://www.law.cornell.edu/uscode/text/8/1182","subs":["(a)(2)(C)(i)","(a)(4)","(a)(7)","(a)(9)(B)","(d)(14)"],"stext":{"head":"§1182. Inadmissible aliens","paras":[[0,"(a) Classes of aliens ineligible for visas or admission"],[0,"Except as otherwise provided in this chapter, aliens who are inadmissible under the following paragraphs are ineligible to receive visas and ineligible to be admitted to the United States:"],[0,"(1) Health-related grounds"],[0,"(A) In general"],[2,"Any alien—"],[3,"(i) who is determined (in accordance with regulations prescribed by the Secretary of Health and Human Services) to have a communicable disease of public health significance; 1"],[3,"(ii) except as provided in subparagraph (C), who seeks admission as an immigrant, or who seeks adjustment of status to the status of an alien lawfully admitted for permanent residence, and who has failed to present documentation of having received vaccination against vaccine-preventable diseases, which shall include at least the following diseases: mumps, measles, rubella, polio, tetanus and diphtheria toxoids, pertussis, influenza type B and hepatitis B, and any other vaccinations against vaccine-preventable diseases recommended by the Advisory Committee for Immunization Practices,"],[3,"(iii) who is determined (in accordance with regulations prescribed by the Secretary of Health and Human Services in consultation with the Attorney General)—"],[4,"(I) to have a physical or mental disorder and behavior associated with the disorder that may pose, or has posed, a threat to the property, safety, or welfare of the alien or others, or"],[4,"(II) to have had a physical or mental disorder and a history of behavior associated with the disorder, which behavior has posed a threat to the property, safety, or welfare of the alien or others and which behavior is likely to recur or to lead to other harmful behavior, or"],[3,"(iv) who is determined (in accordance with regulations prescribed by the Secretary of Health and Human Services) to be a drug abuser or addict,"],[2,"is inadmissible."],[0,"(B) Waiver authorized"],[2,"For provision authorizing waiver of certain clauses of subparagraph (A), see subsection (g)."],[0,"(C) Exception from immunization requirement for adopted children 10 years of age or younger"],[2,"Clause (ii) of subparagraph (A) shall not apply to a child who—"],[3,"(i) is 10 years of age or younger,"],[3,"(ii) is described in subparagraph (F) or (G) of section 1101(b)(1) of this title; 1 and"],[3,"(iii) is seeking an immigrant visa as an immediate relative under section 1151(b) of this title,"],[2,"if, prior to the admission of the child, an adoptive parent or prospective adoptive parent of the child, who has sponsored the child for admission as an immediate relative, has executed an affidavit stating that the parent is aware of the provisions of subparagraph (A)(ii) and will ensure that, within 30 days of the child's admission, or at the earliest time that is medically appropriate, the child will receive the vaccinations identified in such subparagraph."],[0,"(2) Criminal and related grounds"],[0,"(A) Conviction of certain crimes"],[0,"(i) In general"],[3,"Except as provided in clause (ii), any alien convicted of, or who admits having committed, or who admits committing acts which constitute the essential elements of—"],[4,"(I) a crime involving moral turpitude (other than a purely political offense) or an attempt or conspiracy to commit such a crime, or"],[4,"(II) a violation of (or a conspiracy or attempt to violate) any law or regulation of a State, the United States, or a foreign country relating to a controlled substance (as defined in section 802 of title 21),"],[0,"is inadmissible."],[0,"(ii) Exception"],[3,"Clause (i)(I) shall not apply to an alien who committed only one crime if—"],[4,"(I) the crime was committed when the alien was under 18 years of age, and the crime was committed (and the alien released from any confinement to a prison or correctional institution imposed for the crime) more than 5 years before the date of application for a visa or other documentation and the date of application for admission to the United States, or"],[4,"(II) the maximum penalty possible for the crime of which the alien was convicted (or which the alien admits having committed or of which the acts that the alien admits having committed constituted the essential elements) did not exceed imprisonment for one year and, if the alien was convicted of such crime, the alien was not sentenced to a term of imprisonment in excess of 6 months (regardless of the extent to which the sentence was ultimately executed)."],[0,"(B) Multiple criminal convictions"],[2,"Any alien convicted of 2 or more offenses (other than purely political offenses), regardless of whether the conviction was in a single trial or whether the offenses arose from a single scheme of misconduct and regardless of whether the offenses involved moral turpitude, for which the aggregate sentences to confinement were 5 years or more is inadmissible."],[0,"(C) Controlled substance traffickers"],[2,"Any alien who the consular officer or the Attorney General knows or has reason to believe—"],[3,"(i) is or has been an illicit trafficker in any controlled substance or in any listed chemical (as defined in section 802 of title 21), or is or has been a knowing aider, abettor, assister, conspirator, or colluder with others in the illicit trafficking in any such controlled or listed substance or chemical, or endeavored to do so; or"],[3,"(ii) is the spouse, son, or daughter of an alien inadmissible under clause (i), has, within the previous 5 years, obtained any financial or other benefit from the illicit activity of that alien, and knew or reasonably should have known that the financial or other benefit was the product of such illicit activity,"],[2,"is inadmissible."],[0,"(D) Prostitution and commercialized vice"],[2,"Any alien who—"],[3,"(i) is coming to the United States solely, principally, or incidentally to engage in prostitution, or has engaged in prostitution within 10 years of the date of application for a visa, admission, or adjustment of status,"],[3,"(ii) directly or indirectly procures or attempts to procure, or (within 10 years of the date of application for a visa, admission, or adjustment of status) procured or attempted to procure or to import, prostitutes or persons for the purpose of prostitution, or receives or (within such 10-year period) received, in whole or in part, the proceeds of prostitution, or"],[3,"(iii) is coming to the United States to engage in any other unlawful commercialized vice, whether or not related to prostitution,"],[2,"is inadmissible."],[0,"(E) Certain aliens involved in serious criminal activity who have asserted immunity from prosecution"],[2,"Any alien—"],[3,"(i) who has committed in the United States at any time a serious criminal offense (as defined in section 1101(h) of this title),"],[3,"(ii) for whom immunity from criminal jurisdiction was exercised with respect to that offense,"],[3,"(iii) who as a consequence of the offense and exercise of immunity has departed from the United States, and"],[3,"(iv) who has not subsequently submitted fully to the jurisdiction of the court in the United States having jurisdiction with respect to that offense,"],[2,"is inadmissible."],[0,"(F) Waiver authorized"],[2,"For provision authorizing waiver of certain subparagraphs of this paragraph, see subsection (h)."],[0,"(G) Foreign government officials who have committed particularly severe violations of religious freedom"],[2,"Any alien who, while serving as a foreign government official, was responsible for or directly carried out, at any time, particularly severe violations of religious freedom, as defined in section 6402 of title 22, is inadmissible."],[0,"(H) Significant traffickers in persons"],[0,"(i) In general"],[3,"Any alien who commits or conspires to commit human trafficking offenses in the United States or outside the United States, or who the consular officer, the Secretary of Homeland Security, the Secretary of State, or the Attorney General knows or has reason to believe is or has been a knowing aider, abettor, assister, conspirator, or colluder with such a trafficker in severe forms of trafficking in persons, as defined in the section 7102 of title 22, is inadmissible."],[0,"(ii) Beneficiaries of trafficking"],[3,"Except as provided in clause (iii), any alien who the consular officer or the Attorney General knows or has reason to believe is the spouse, son, or daughter of an alien inadmissible under clause (i), has, within the previous 5 years, obtained any financial or other benefit from the illicit activity of that alien, and knew or reasonably should have known that the financial or other benefit was the product of such illicit activity, is inadmissible."],[0,"(iii) Exception for certain sons and daughters"],[3,"Clause (ii) shall not apply to a son or daughter who was a child at the time he or she received the benefit described in such clause."],[0,"(I) Money laundering"],[2,"Any alien—"],[3,"(i) who a consular officer or the Attorney General knows, or has reason to believe, has engaged, is engaging, or seeks to enter the United States to engage, in an offense which is described in section 1956 or 1957 of title 18 (relating to laundering of monetary instruments); or"],[3,"(ii) who a consular officer or the Attorney General knows is, or has been, a knowing aider, abettor, assister, conspirator, or colluder with others in an offense which is described in such section;"],[2,"is inadmissible."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1182?type=usc&year=mostrecent&link-type=html"},"by":{"1":"30, 36, 36, 4, 20"},"q":[{"src":"opinion","who":"Opinion of the Court (Justice Kagan)","text":"for urgent humanitarian reasons or signifcant public beneft.","cite":"8 U. S. C. § 1182(d)(5)(A)"}]},{"t":"usc","label":"8 U.S.C. § 1184","url":"https://www.law.cornell.edu/uscode/text/8/1184","subs":["(a)(1)","(b)","(p)"],"stext":{"head":"§1184. Admission of nonimmigrants","paras":[[0,"(a) Regulations"],[0,"(1) The admission to the United States of any alien as a nonimmigrant shall be for such time and under such conditions as the Attorney General may by regulations prescribe, including when he deems necessary the giving of a bond with sufficient surety in such sum and containing such conditions as the Attorney General shall prescribe, to insure that at the expiration of such time or upon failure to maintain the status under which he was admitted, or to maintain any status subsequently acquired under section 1258 of this title, such alien will depart from the United States. No alien admitted to Guam or the Commonwealth of the Northern Mariana Islands without a visa pursuant to section 1182(l) of this title may be authorized to enter or stay in the United States other than in Guam or the Commonwealth of the Northern Mariana Islands or to remain in Guam or the Commonwealth of the Northern Mariana Islands for a period exceeding 45 days from date of admission to Guam or the Commonwealth of the Northern Mariana Islands. No alien admitted to the United States without a visa pursuant to section 1187 of this title may be authorized to remain in the United States as a nonimmigrant visitor for a period exceeding 90 days from the date of admission."],[0,"(2)(A) The period of authorized status as a nonimmigrant described in section 1101(a)(15)(O) of this title shall be for such period as the Attorney General may specify in order to provide for the event (or events) for which the nonimmigrant is admitted."],[0,"(B) The period of authorized status as a nonimmigrant described in section 1101(a)(15)(P) of this title shall be for such period as the Attorney General may specify in order to provide for the competition, event, or performance for which the nonimmigrant is admitted. In the case of nonimmigrants admitted as individual athletes under section 1101(a)(15)(P) of this title, the period of authorized status may be for an initial period (not to exceed 5 years) during which the nonimmigrant will perform as an athlete and such period may be extended by the Attorney General for an additional period of up to 5 years."],[0,"(b) Presumption of status; written waiver"],[0,"Every alien (other than a nonimmigrant described in subparagraph (L) or (V) of section 1101(a)(15) of this title, and other than a nonimmigrant described in any provision of section 1101(a)(15)(H)(i) of this title except subclause (b1) of such section) shall be presumed to be an immigrant until he establishes to the satisfaction of the consular officer, at the time of application for a visa, and the immigration officers, at the time of application for admission, that he is entitled to a nonimmigrant status under section 1101(a)(15) of this title. An alien who is an officer or employee of any foreign government or of any international organization entitled to enjoy privileges, exemptions, and immunities under the International Organizations Immunities Act [22 U.S.C. 288 et seq.], or an alien who is the attendant, servant, employee, or member of the immediate family of any such alien shall not be entitled to apply for or receive an immigrant visa, or to enter the United States as an immigrant unless he executes a written waiver in the same form and substance as is prescribed by section 1257(b) of this title."],[0,"(c) Petition of importing employer"],[0,"(1) The question of importing any alien as a nonimmigrant under subparagraph (H), (L), (O), or (P)(i) of section 1101(a)(15) of this title (excluding nonimmigrants under section 1101(a)(15)(H)(i)(b1) of this title) in any specific case or specific cases shall be determined by the Attorney General, after consultation with appropriate agencies of the Government, upon petition of the importing employer. Such petition, shall be made and approved before the visa is granted. The petition shall be in such form and contain such information as the Attorney General shall prescribe. The approval of such a petition shall not, of itself, be construed as establishing that the alien is a nonimmigrant. For purposes of this subsection with respect to nonimmigrants described in section 1101(a)(15)(H)(ii)(a) of this title, the term \"appropriate agencies of Government\" means the Department of Labor and includes the Department of Agriculture. The provisions of section 1188 of this title shall apply to the question of importing any alien as a nonimmigrant under section 1101(a)(15)(H)(ii)(a) of this title."],[0,"(2)(A) The Attorney General shall provide for a procedure under which an importing employer which meets requirements established by the Attorney General may file a blanket petition to import aliens as nonimmigrants described in section 1101(a)(15)(L) of this title instead of filing individual petitions under paragraph (1) to import such aliens. Such procedure shall permit the expedited processing of visas for admission of aliens covered under such a petition."],[0,"(B) For purposes of section 1101(a)(15)(L) of this title, an alien is considered to be serving in a capacity involving specialized knowledge with respect to a company if the alien has a special knowledge of the company product and its application in international markets or has an advanced level of knowledge of processes and procedures of the company."],[0,"(C) The Attorney General shall provide a process for reviewing and acting upon petitions under this subsection with respect to nonimmigrants described in section 1101(a)(15)(L) of this title within 30 days after the date a completed petition has been filed."],[0,"(D) The period of authorized admission for—"],[1,"(i) a nonimmigrant admitted to render services in a managerial or executive capacity under section 1101(a)(15)(L) of this title shall not exceed 7 years, or"],[1,"(ii) a nonimmigrant admitted to render services in a capacity that involves specialized knowledge under section 1101(a)(15)(L) of this title shall not exceed 5 years."],[0,"(E) In the case of an alien spouse admitted under section 1101(a)(15)(L) of this title, who is accompanying or following to join a principal alien admitted under such section, the Attorney General shall authorize the alien spouse to engage in employment in the United States and provide the spouse with an \"employment authorized\" endorsement or other appropriate work permit."],[0,"(F) An alien who will serve in a capacity involving specialized knowledge with respect to an employer for purposes of section 1101(a)(15)(L) of this title and will be stationed primarily at the worksite of an employer other than the petitioning employer or its affiliate, subsidiary, or parent shall not be eligible for classification under section 1101(a)(15)(L) of this title if—"],[1,"(i) the alien will be controlled and supervised principally by such unaffiliated employer; or"],[1,"(ii) the placement of the alien at the worksite of the unaffiliated employer is essentially an arrangement to provide labor for hire for the unaffiliated employer, rather than a placement in connection with the provision of a product or service for which specialized knowledge specific to the petitioning employer is necessary."],[0,"(3) The Attorney General shall approve a petition—"],[1,"(A) with respect to a nonimmigrant described in section 1101(a)(15)(O)(i) of this title only after consultation in accordance with paragraph (6) or, with respect to aliens seeking entry for a motion picture or television production, after consultation with the appropriate union representing the alien's occupational peers and a management organization in the area of the alien's ability, or"],[1,"(B) with respect to a nonimmigrant described in section 1101(a)(15)(O)(ii) of this title after consultation in accordance with paragraph (6) or, in the case of such an alien seeking entry for a motion picture or television production, after consultation with such a labor organization and a management organization in the area of the alien's ability."],[0,"In the case of an alien seeking entry for a motion picture or television production, (i) any opinion under the previous sentence shall only be advisory, (ii) any such opinion that recommends denial must be in writing, (iii) in making the decision the Attorney General shall consider the exigencies and scheduling of the production, and (iv) the Attorney General shall append to the decision any such opinion. The Attorney General shall provide by regulation for the waiver of the consultation requirement under subparagraph (A) in the case of aliens who have been admitted as nonimmigrants under section 1101(a)(15)(O)(i) of this title because of extraordinary ability in the arts and who seek readmission to perform similar services within 2 years after the date of a consultation under such subparagraph. Not later than 5 days after the date such a waiver is provided, the Attorney General shall forward a copy of the petition and all supporting documentation to the national office of an appropriate labor organization."],[0,"(4)(A) For purposes of section 1101(a)(15)(P)(i)(a) of this title, an alien is described in this subparagraph if the alien—"],[1,"(i)(I) performs as an athlete, individually or as part of a group or team, at an internationally recognized level of performance;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1184?type=usc&year=mostrecent&link-type=html"},"by":{"1":"35, 35, 35, 35"},"q":[{"src":"brief","b":1,"text":"[t]he admission to the United States of any alien as a nonimmigrant shall be for such time and under such conditions as [the Secretary] may by regulations prescribe,","cite":"8 U.S.C. 1184(a)(1)"},{"src":"argument","who":"Ms. Saharia","text":"Well, I think you would look to Section 1184 of the INA, which is the section that authorizes the government to confer non-immigrant status on individuals, and that statute refers to that process as admission."},{"src":"argument","who":"Justice Kagan","text":"But just the fact that 1255(m) could have been written without saying something like, you know, notwithstanding Section 1184, suggests that there's no rule of the kind that you're talking about in the first instance."},{"src":"argument","who":"Mr. Huston","text":"And it makes sense that Congress, in Section 1184, wrote a provision granting the service authority to set some of the restrictions and requirements for that admission process and then imposing some of Congress's own."}]},{"t":"usc","label":"8 U.S.C. § 1225","url":"https://www.law.cornell.edu/uscode/text/8/1225","subs":["(a)(1988)","(b)(1988)"],"by":{"1":"35, 35"}},{"t":"usc","label":"8 U.S.C. § 1254a","url":"https://www.law.cornell.edu/uscode/text/8/1254a","subs":["(a)(1)","(a)(1)(A)","(a)(5)","(b)(1)","(b)(1)(C)","(b)(2)","(b)(3)(A)","(b)(3)(C)","(c)","(c)(1)(A)(i)","(c)(1)(A)(iii)","(c)(2)(A)","(c)(2)(A)(ii)","(c)(2)(A)(iii)(II)","(c)(5)","(h)(1)"],"by":{"1":"41, 41, 41, 41, 41, 41, 41, 41, 41, 41, 41, 41, 41, 41, 41, 41, 41, 41, 41, 41, 41, 41"},"q":[{"src":"brief","b":1,"text":"for purposes of adjustment of status under [8 U.S.C. 1255] and change of status under [8 U.S.C. 1258], the alien shall be considered as being in, and maintaining, lawful status as a nonimmigrant.","cite":"8 U.S.C. 1254a"},{"src":"brief","b":1,"text":"considered as being in, and maintaining, lawful status as a nonimmigrant,","cite":"8 U.S.C. 1254a"}]},{"t":"usc","label":"8 U.S.C. § 1255","url":"https://www.law.cornell.edu/uscode/text/8/1255","subs":["(a)","(a)(2)","(a)(3)","(b)","(c)(1)","(c)(2)(1988)","(c)(2)","(c)(7)","(c)(8)","(g)","(h)","(h)(1)","(i)","(i)(1)(A)(i)","(k)","(k)(1)","(k)(2)","(l)","(m)","(m)(1)","(b)(1988)"],"stext":{"head":"§1255. Adjustment of status of nonimmigrant to that of person admitted for permanent residence","paras":[[0,"(a) Status as person admitted for permanent residence on application and eligibility for immigrant visa"],[0,"The status of an alien who was inspected and admitted or paroled into the United States or the status of any other alien having an approved petition for classification as a VAWA self-petitioner may be adjusted by the Attorney General, in his discretion and under such regulations as he may prescribe, to that of an alien lawfully admitted for permanent residence if (1) the alien makes an application for such adjustment, (2) the alien is eligible to receive an immigrant visa and is admissible to the United States for permanent residence, and (3) an immigrant visa is immediately available to him at the time his application is filed."],[0,"(b) Record of lawful admission for permanent residence; reduction of preference visas"],[0,"Upon the approval of an application for adjustment made under subsection (a), the Attorney General shall record the alien's lawful admission for permanent residence as of the date the order of the Attorney General approving the application for the adjustment of status is made, and the Secretary of State shall reduce by one the number of the preference visas authorized to be issued under sections 1152 and 1153 of this title within the class to which the alien is chargeable for the fiscal year then current."],[0,"(c) Alien crewmen, aliens continuing or accepting unauthorized employment, and aliens admitted in transit without visa"],[0,"Other than an alien having an approved petition for classification as a VAWA self-petitioner, subsection (a) shall not be applicable to (1) an alien crewman; (2) subject to subsection (k), an alien (other than an immediate relative as defined in section 1151(b) of this title or a special immigrant described in section 1101(a)(27)(H), (I), (J), or (K) of this title) who hereafter continues in or accepts unauthorized employment prior to filing an application for adjustment of status or who is in unlawful immigration status on the date of filing the application for adjustment of status or who has failed (other than through no fault of his own or for technical reasons) to maintain continuously a lawful status since entry into the United States; (3) any alien admitted in transit without visa under section 1182(d)(4)(C) of this title; (4) an alien (other than an immediate relative as defined in section 1151(b) of this title) who was admitted as a nonimmigrant visitor without a visa under section 1182(l) of this title or section 1187 of this title; (5) an alien who was admitted as a nonimmigrant described in section 1101(a)(15)(S) of this title,1 (6) an alien who is deportable under section 1227(a)(4)(B) of this title; (7) any alien who seeks adjustment of status to that of an immigrant under section 1153(b) of this title and is not in a lawful nonimmigrant status; or (8) any alien who was employed while the alien was an unauthorized alien, as defined in section 1324a(h)(3) of this title, or who has otherwise violated the terms of a nonimmigrant visa."],[0,"(d) Alien admitted for permanent residence on conditional basis; fiancee or fiance of citizen"],[0,"The Attorney General may not adjust, under subsection (a), the status of an alien lawfully admitted to the United States for permanent residence on a conditional basis under section 1186a of this title. The Attorney General may not adjust, under subsection (a), the status of a nonimmigrant alien described in section 1101(a)(15)(K) of this title except to that of an alien lawfully admitted to the United States on a conditional basis under section 1186a of this title as a result of the marriage of the nonimmigrant (or, in the case of a minor child, the parent) to the citizen who filed the petition to accord that alien's nonimmigrant status under section 1101(a)(15)(K) of this title."],[0,"(e) Restriction on adjustment of status based on marriages entered while in admissibility or deportation proceedings; bona fide marriage exception"],[0,"(1) Except as provided in paragraph (3), an alien who is seeking to receive an immigrant visa on the basis of a marriage which was entered into during the period described in paragraph (2) may not have the alien's status adjusted under subsection (a)."],[0,"(2) The period described in this paragraph is the period during which administrative or judicial proceedings are pending regarding the alien's right to be admitted or remain in the United States."],[0,"(3) Paragraph (1) and section 1154(g) of this title shall not apply with respect to a marriage if the alien establishes by clear and convincing evidence to the satisfaction of the Attorney General that the marriage was entered into in good faith and in accordance with the laws of the place where the marriage took place and the marriage was not entered into for the purpose of procuring the alien's admission as an immigrant and no fee or other consideration was given (other than a fee or other consideration to an attorney for assistance in preparation of a lawful petition) for the filing of a petition under section 1154(a) of this title or subsection (d) or (p) 2 of section 1184 of this title with respect to the alien spouse or alien son or daughter. In accordance with regulations, there shall be only one level of administrative appellate review for each alien under the previous sentence."],[0,"(f) Limitation on adjustment of status"],[0,"The Attorney General may not adjust, under subsection (a), the status of an alien lawfully admitted to the United States for permanent residence on a conditional basis under section 1186b of this title."],[0,"(g) Special immigrants"],[0,"In applying this section to a special immigrant described in section 1101(a)(27)(K) of this title, such an immigrant shall be deemed, for purposes of subsection (a), to have been paroled into the United States."],[0,"(h) Application with respect to special immigrants"],[0,"In applying this section to a special immigrant described in section 1101(a)(27)(J) of this title—"],[1,"(1) such an immigrant shall be deemed, for purposes of subsection (a), to have been paroled into the United States; and"],[1,"(2) in determining the alien's admissibility as an immigrant—"],[2,"(A) paragraphs (4), (5)(A), (6)(A), (6)(C), (6)(D), (7)(A), and (9)(B) of section 1182(a) of this title shall not apply; and"],[2,"(B) the Attorney General may waive other paragraphs of section 1182(a) of this title (other than paragraphs (2)(A), (2)(B), (2)(C) (except for so much of such paragraph as related to a single offense of simple possession of 30 grams or less of marijuana), (3)(A), (3)(B), (3)(C), and (3)(E)) in the case of individual aliens for humanitarian purposes, family unity, or when it is otherwise in the public interest."],[0,"The relationship between an alien and the alien's natural parents or prior adoptive parents shall not be considered a factor in making a waiver under paragraph (2)(B). Nothing in this subsection or section 1101(a)(27)(J) of this title shall be construed as authorizing an alien to apply for admission or be admitted to the United States in order to obtain special immigrant status described in such section."],[0,"(i) Adjustment in status of certain aliens physically present in United States"],[0,"(1) Notwithstanding the provisions of subsections (a) and (c) of this section, an alien physically present in the United States—"],[1,"(A) who—"],[2,"(i) entered the United States without inspection; or"],[2,"(ii) is within one of the classes enumerated in subsection (c) of this section;"],[1,"(B) who is the beneficiary (including a spouse or child of the principal alien, if eligible to receive a visa under section 1153(d) of this title) of—"],[2,"(i) a petition for classification under section 1154 of this title that was filed with the Attorney General on or before April 30, 2001; or"],[2,"(ii) an application for a labor certification under section 1182(a)(5)(A) of this title that was filed pursuant to the regulations of the Secretary of Labor on or before such date; and"],[1,"(C) who, in the case of a beneficiary of a petition for classification, or an application for labor certification, described in subparagraph (B) that was filed after January 14, 1998, is physically present in the United States on December 21, 2000;"],[0,"may apply to the Attorney General for the adjustment of his or her status to that of an alien lawfully admitted for permanent residence. The Attorney General may accept such application only if the alien remits with such application a sum equalling $1,000 as of the date of receipt of the application, but such sum shall not be required from a child under the age of seventeen, or an alien who is the spouse or unmarried child of an individual who obtained temporary or permanent resident status under section 1160 or 1255a of this title or section 202 of the Immigration Reform and Control Act of 1986 at any date, who—"],[1,"(i) as of May 5, 1988, was the unmarried child or spouse of the individual who obtained temporary or permanent resident status under section 1160 or 1255a of this title or section 202 of the Immigration Reform and Control Act of 1986;"],[1,"(ii) entered the United States before May 5, 1988, resided in the United States on May 5, 1988, and is not a lawful permanent resident; and"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1255?type=usc&year=mostrecent&link-type=html"},"by":{"1":"41, 41, 41, 41, 41, 41, 41, 41, 41, 41, 41, 41, 41, 41, 41, 41, 41, 41, 41, 41, 41, 41","2":"7"},"q":[{"src":"brief","b":1,"text":"to that of an alien lawfully admitted for permanent residence.","cite":"8 U.S.C. 1255(a)"},{"src":"brief","b":1,"text":"inspected and admitted or paroled into the United States.","cite":"8 U.S.C. 1255(a)"},{"src":"argument","who":"Ms. Saharia","text":"And the government said no need to worry about that language; that language simply explains someone may already be admitted as a non-immigrant in a different classification and then change into the U visa status classification under Section 1255."},{"src":"argument","who":"Ms. Saharia","text":"But Section (f)(4) doesn't create a new mechanism. It just gives otherwise eligible TPS recipients access to the existing mechanism in Section 1255."},{"src":"argument","who":"Justice Sotomayor","text":"By the plain text, it seems to me that any TPS holder who is granted permission to travel abroad and return would be admitted within the meaning of Section 1255."}]},{"t":"usc","label":"8 U.S.C. § 1258","url":"https://www.law.cornell.edu/uscode/text/8/1258","subs":["(a)"],"stext":{"head":"§1258. Change of nonimmigrant classification","paras":[[0,"(a) The Secretary of Homeland Security may, under such conditions as he may prescribe, authorize a change from any nonimmigrant classification to any other nonimmigrant classification in the case of any alien lawfully admitted to the United States as a nonimmigrant who is continuing to maintain that status and who is not inadmissible under section 1182(a)(9)(B)(i) of this title (or whose inadmissibility under such section is waived under section 1182(a)(9)(B)(v) of this title), except (subject to subsection (b)) in the case of—"],[1,"(1) an alien classified as a nonimmigrant under subparagraph (C), (D), (K), or (S) of section 1101(a)(15) of this title,"],[1,"(2) an alien classified as a nonimmigrant under subparagraph (J) of section 1101(a)(15) of this title who came to the United States or acquired such classification in order to receive graduate medical education or training,"],[1,"(3) an alien (other than an alien described in paragraph (2)) classified as a nonimmigrant under subparagraph (J) of section 1101(a)(15) of this title who is subject to the two-year foreign residence requirement of section 1182(e) of this title and has not received a waiver thereof, unless such alien applies to have the alien's classification changed from classification under subparagraph (J) of section 1101(a)(15) of this title to a classification under subparagraph (A) or (G) of such section, and"],[1,"(4) an alien admitted as a nonimmigrant visitor without a visa under section 1182(l) of this title or section 1187 of this title."],[0,"(b) The exceptions specified in paragraphs (1) through (4) of subsection (a) shall not apply to a change of nonimmigrant classification to that of a nonimmigrant under subparagraph (T) or (U) of section 1101(a)(15) of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1258?type=usc&year=mostrecent&link-type=html"},"by":{"1":"41, 41"},"q":[{"src":"brief","b":1,"text":"lawfully admitted to the United States as a nonimmigrant [and] is continuing to maintain that status.","cite":"8 U.S.C. 1258(a)"},{"src":"argument","who":"Ms. Saharia","text":"For example, deeming TPS recipients simply to have been inspected and admitted would not have permitted TPS recipients to change to non-immigrant status under Section 1258, and we know Congress intended that as well because it cross-referenced Section 1258."},{"src":"argument","who":"Ms. Saharia","text":"I don't think that's the case, because Congress used broad language that -- that both satisfies Section 1255(a) but also satisfies Section 1258."},{"src":"argument","who":"Ms. Saharia","text":"A great example of that is Section 1258 governing a change of status, which Congress expressly cross-referenced in (f)(4), the provision at issue."}]},{"t":"usc","label":"6 U.S.C. § 271","url":"https://www.law.cornell.edu/uscode/text/6/271","subs":["(b)(5)"],"by":{"1":"2"}},{"t":"usc","label":"6 U.S.C. § 557","url":"https://www.law.cornell.edu/uscode/text/6/557","by":{"1":"2"}},{"t":"reg","label":"56 Fed. Reg. 23,491","url":"https://www.govinfo.gov/link/fr/56/23491","by":{"1":"6, 41, 43"}},{"t":"reg","label":"Temporary Protected Status: Interim rule with request for comments, 56 Fed. Reg. 618","url":"https://www.govinfo.gov/link/fr/56/618","by":{"1":"43","2":"20"}},{"t":"case","label":"Duncan v. Walker","cite":"533 U.S. 167","y":2001,"id":"2000/00-121","sc":1,"by":{"2":"13"}},{"t":"case","label":"Gitlitz v. Comm’r","cite":"531 U.S. 206","y":2001,"id":"2000/99-1295","sc":1,"by":{"2":"6"},"q":[{"src":"brief","b":2,"text":"[T]here would be no need to provide [such] an exception","cite":"531 U.S. 206, 214"}]},{"t":"case","label":"Kingdomware Techs. v. United States","cite":"136 S. Ct. 1969","y":2016,"id":"2015/14-916","sc":1,"by":{"2":"20"}},{"t":"case","label":"OBB Personenverkehr AG v. Sachs","cite":"577 U.S. 27","y":2015,"id":"2015/13-1067","sc":1,"by":{"2":"19"}},{"t":"case","label":"Perez v. Mortg. Bankers Ass’n","cite":"575 U.S. 92","y":2015,"id":"2014/13-1041","sc":1,"by":{"2":"20"},"q":[{"src":"brief","b":2,"text":"advise the public of the agency’s construction of the statute,","cite":"575 U.S. 92, 97"}]},{"t":"case","label":"Russello v. United States","cite":"464 U.S. 16","y":1983,"id":"1983/82-472","sc":1,"by":{"2":"15, 16"}},{"t":"case","label":"United States v. Texas","cite":"507 U.S. 529","y":1993,"id":"1992/91-1729","sc":1,"by":{"2":"9"},"q":[{"src":"brief","b":2,"text":"hazardous basis for inferring the intent of an earlier Congress.","cite":"507 U.S. 529, 535 n.4"}]},{"t":"case","label":"United States v. Wells","cite":"519 U.S. 482","y":1997,"id":"1996/95-1228","sc":1,"by":{"2":"10"},"q":[{"src":"brief","b":2,"text":"[I]t is at best treacherous to find in congressional silence alone the adoption of a controlling rule of law.","cite":"519 U.S. 482, 496"}]},{"t":"case","label":"Wyeth v. Levine","cite":"555 U.S. 555","y":2009,"id":"2008/06-1249","sc":1,"by":{"2":"20"}},{"t":"law","label":"Pub. L. No. 102-232","by":{"2":"10"}},{"t":"reg","label":"8 C.F.R. § 204.2","url":"https://www.ecfr.gov/current/title-8/section-204.2","subs":["(c)"],"by":{"2":"9"}},{"t":"reg","label":"8 C.F.R. § 245.1","url":"https://www.ecfr.gov/current/title-8/section-245.1","subs":["(c)(1)(ii)"],"by":{"2":"5"},"q":[{"src":"brief","b":2,"text":"[a]dmitted in nonimmigrant status as defined in section 101(a)(15) of the Act.","cite":"8 C.F.R. § 245.1(c)(1)(ii)"}]},{"t":"reg","label":"Temporary Protected Status, 56 Fed. Reg. 23,495","url":"https://www.govinfo.gov/link/fr/56/23495","by":{"2":"19, 20, 21, 23"}}]};